"""Record layouts for payroll. Generated by Séance from the COBOL record descriptions. Do not edit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from seance.cobol_num import deedit, format_alpha, format_edited, format_numeric, parse_numeric

IN_WIDTH = 15
OUT_WIDTH = 31


@dataclass
class InRecord:
    emp_id: str
    hours: Decimal
    rate: Decimal

    @classmethod
    def parse(cls, line: str) -> "InRecord":
        line = line.ljust(15)
        return cls(
            emp_id=line[0:6].rstrip(),
            hours=parse_numeric(line[6:10], 4, 1, False, 'none'),
            rate=parse_numeric(line[10:15], 5, 2, False, 'none'),
        )

    def format(self) -> str:
        return (
            format_alpha(self.emp_id, 6)
            + format_numeric(self.hours, 4, 1, False, 'none')
            + format_numeric(self.rate, 5, 2, False, 'none')
        ).rstrip()


@dataclass
class OutRecord:
    emp_id: str
    gross: Decimal
    tax: Decimal
    net: Decimal

    @classmethod
    def parse(cls, line: str) -> "OutRecord":
        line = line.ljust(31)
        return cls(
            emp_id=line[0:6].rstrip(),
            gross=parse_numeric(line[6:14], 8, 2, False, 'none'),
            tax=parse_numeric(line[14:22], 8, 2, False, 'none'),
            net=parse_numeric(line[22:31], 8, 2, True, 'leading_sep'),
        )

    def format(self) -> str:
        return (
            format_alpha(self.emp_id, 6)
            + format_numeric(self.gross, 8, 2, False, 'none')
            + format_numeric(self.tax, 8, 2, False, 'none')
            + format_numeric(self.net, 8, 2, True, 'leading_sep')
        ).rstrip()

